
local str_format=string.format
local root_tree
local pktinfo

-- actual protocol registration
local isarProto=Proto("ISAR_APIID90", "ISAR/Sack 5G Patch v1.0.1 for TTI streaming miodule test")
isarProto.fields={}

-- SYSCOM info needed by decoder
local f_Endianess = Field.new("sic.flags2.mapf") -- explore endian field from inside syscom protocol layer
local f_msgId     = Field.new("sic.msgid")       -- extract msgid from syscom layer

-- Utility wrapper for endian-aware decoding of integers

function subtree_add_le(self, subtree, field, msgBuffPart)
   return subtree:add_le(field, msgBuffPart)
end

function subtree_add_be(self, subtree,field, msgBuffPart)
   return subtree:add(field, msgBuffPart)
end

function le_return_uint(self, msgbuf_range)
   return msgbuf_range:le_uint()
end

function be_return_uint(self, msgbuf_range)
   return msgbuf_range:uint()
end

local wrapper = {}

function wrapper:init()
   if(tostring(f_Endianess()) == "0x00000001" or
      tostring(f_Endianess()) == "0x00000003") then
      wrapper.subtree_add = subtree_add_le;
      wrapper.uint = le_return_uint;
   else
      wrapper.subtree_add = subtree_add_be;
      wrapper.uint = be_return_uint;
   end
end

-- Utility functions for creating expandable subtrees in the info Wireshark displays

function createSubTree (msg_tree, fieldName, place, buffer_handle) 
  if fieldName ~= "" then 
    local block_tree = msg_tree:add(place, buffer_handle)
    block_tree:set_text(str_format("%s:", fieldName))
    return block_tree
  else 
    return msg_tree
  end 
end 

function createSubTree2 (msg_tree, buffer_handle, fieldName) 
  if fieldName ~= "" then 
    local block_tree = msg_tree:add(buffer_handle, fieldName)
    block_tree:set_text(str_format("%s:", fieldName))
    return block_tree
  else 
    return msg_tree
  end 
end 


function determineSafeStructSize(expectedSize, buffer, tree)
    local safeSize = math.min(expectedSize, buffer:len())
    
    if safeSize < expectedSize then
        tree:add_expert_info(PI_MALFORMED, PI_WARN, "Expected struct length was " .. tostring(expectedSize) .. ", actual struct length was " ..
                                                    tostring(buffer:len()) .. ", trying to decode as much as possible")
    end

    return safeSize
end

