-- functions for byte-by-byte decoding of message buffer

function build_BTSOM_ApDiscoveryReadyInd (p_wrapper, root_msg_buf, msg_tree, fieldName, lhsName, actual_offset, p_protocol) 
  local totalStructSize = 56
  local msg_buf_handle = root_msg_buf(actual_offset, determineSafeStructSize(totalStructSize, root_msg_buf, msg_tree))
  local msg_buf = msg_buf_handle:tvb()

  local block_tree = createSubTree2(msg_tree, msg_buf_handle, fieldName)
  local current
  
  do 
      local arrayLen = 46
      local array_tree = createSubTree2(block_tree, msg_buf(0, 46), "masterIpAddress")
      for i=0, arrayLen-1 do 
          current = msg_buf(0  + i * 1, 1)
          p_wrapper:subtree_add(array_tree, isarProto.fields[lhsName .. "_masterIpAddress"], current)
          
        end 
    end 
  current = msg_buf(48 , 4)
  p_wrapper:subtree_add(block_tree, isarProto.fields[lhsName .. "_masterPortNum"], current)
  
  current = msg_buf(52 , 4)
  local enum_neType = block_tree:add(isarProto.fields[lhsName .. "_neType"], current)

  enum_neType:set_text(str_format("neType: %s", enums.ENeType[p_wrapper:uint(current)]))
  
  return ( actual_offset + totalStructSize )
end 

function build_BTSOM_ApResetReq (p_wrapper, root_msg_buf, msg_tree, fieldName, lhsName, actual_offset, p_protocol) 
  local totalStructSize = 4
  local msg_buf_handle = root_msg_buf(actual_offset, determineSafeStructSize(totalStructSize, root_msg_buf, msg_tree))
  local msg_buf = msg_buf_handle:tvb()

