function build_SSourceAddresses (p_wrapper, root_msg_buf, msg_tree, fieldName, lhsName, actual_offset, p_protocol) 
  local totalStructSize = 52
  local msg_buf_handle = root_msg_buf(actual_offset, determineSafeStructSize(totalStructSize, root_msg_buf, msg_tree))
  local msg_buf = msg_buf_handle:tvb()

  local block_tree = createSubTree2(msg_tree, msg_buf_handle, fieldName)
  local current
  
  build_STransportLayerAddress(p_wrapper, msg_buf, block_tree, "transportLayerAddress", lhsName .. "_transportLayerAddress", 0 , p_protocol)
  
  do 
      local optFlag = msg_buf(24, 4)
      if p_wrapper:uint(optFlag) ~= 0 then 
        local inner_tree = createSubTree2(block_tree, msg_buf(24, 28), "transportLayerAddressSec")
        p_wrapper:subtree_add(inner_tree, isarProto.fields[lhsName .. "_hasTransportLayerAddressSec"], optFlag)
        build_STransportLayerAddress(p_wrapper, msg_buf, inner_tree, "transportLayerAddressSec", lhsName .. "_transportLayerAddressSec", 28 , p_protocol)
        
      else 
        local replacement_text = p_wrapper:subtree_add(block_tree, isarProto.fields[lhsName .. "_hasTransportLayerAddressSec"], optFlag)

        replacement_text:set_text("transportLayerAddressSec: <omit>")
      end 
    end 
  return ( actual_offset + totalStructSize )
end 

