function build_SUeBearerReleaseInfo (p_wrapper, root_msg_buf, msg_tree, fieldName, lhsName, actual_offset, p_protocol) 
  local totalStructSize = 132
  local msg_buf_handle = root_msg_buf(actual_offset, determineSafeStructSize(totalStructSize, root_msg_buf, msg_tree))
  local msg_buf = msg_buf_handle:tvb()

  local block_tree = createSubTree2(msg_tree, msg_buf_handle, fieldName)
  local current
  
  do 
      local union_tree = createSubTree2(block_tree, msg_buf(0, 8), "ueId")
      local discriminator = msg_buf(0  + 0, 4)
      if p_wrapper:uint(discriminator) == EUUeId_UeId then 
        current = msg_buf(0  + 4, 4)
        p_wrapper:subtree_add(union_tree, isarProto.fields[lhsName .. "_ueId_u_ueId"], current)
        
      end 
      if p_wrapper:uint(discriminator) == EUUeId_UeS1X2Id then 
        current = msg_buf(0  + 4, 4)
        p_wrapper:subtree_add(union_tree, isarProto.fields[lhsName .. "_ueId_u_ueS1APId"], current)
        
      end 
    end 
  do 
      local numField = msg_buf(8, 4)
      local arrayLen = p_wrapper:uint(numField)

      local array_tree = createSubTree2(block_tree, msg_buf(12, arrayLen * 12), "bearerReleaseInfo")
      p_wrapper:subtree_add(array_tree, isarProto.fields[lhsName .. "_numOfBearerReleaseInfo"], numField)
      for i=0, arrayLen-1 do 
          build_SBearerReleaseInfo(p_wrapper, msg_buf, array_tree, "bearerReleaseInfo" .. "[" .. i .. "]", lhsName .. "_bearerReleaseInfo", 12  + i * 12, p_protocol)
          
        end 
    end 
  return ( actual_offset + totalStructSize )
end 

