function build_SUeHistoryInformation (p_wrapper, root_msg_buf, msg_tree, fieldName, lhsName, actual_offset, p_protocol) 
  local totalStructSize = 856
  local msg_buf_handle = root_msg_buf(actual_offset, determineSafeStructSize(totalStructSize, root_msg_buf, msg_tree))
  local msg_buf = msg_buf_handle:tvb()

  local block_tree = createSubTree2(msg_tree, msg_buf_handle, fieldName)
  local current
  
  do 
      local numField = msg_buf(0, 4)
      local arrayLen = p_wrapper:uint(numField)

      local array_tree = createSubTree2(block_tree, msg_buf(4, arrayLen * 52), "items")
      p_wrapper:subtree_add(array_tree, isarProto.fields[lhsName .. "_numOfItems"], numField)
      for i=0, arrayLen-1 do 
          do 
              local union_tree = createSubTree2(array_tree, msg_buf(4, 832), "items")
              local discriminator = msg_buf(4  + i * 52 + 0, 4)
              if p_wrapper:uint(discriminator) == 0 then 
                build_SLastVisitedEUTRANCellItem(p_wrapper, msg_buf, union_tree, "u.eUTRANCell" .. "[" .. i .. "]", lhsName .. "_items_u_eUTRANCell", 4  + i * 52 + 4, p_protocol)
                
              end 
              if p_wrapper:uint(discriminator) == 1 then 
                build_SLastVisitedUTRANCellItem(p_wrapper, msg_buf, union_tree, "u.uTRANCell" .. "[" .. i .. "]", lhsName .. "_items_u_uTRANCell", 4  + i * 52 + 4, p_protocol)
                
              end 
              if p_wrapper:uint(discriminator) == 2 then 
                current = msg_buf(4  + i * 52 + 4, 1)
                p_wrapper:subtree_add(union_tree, isarProto.fields[lhsName .. "_items_u_gERANCell"], current)
                
              end 
            end 
        end 
    end 
  current = msg_buf(836 , 4)
  p_wrapper:subtree_add(block_tree, isarProto.fields[lhsName .. "_pingPongDetectionCompleted"], current)
  
  do 
      local optFlag = msg_buf(840, 4)
      if p_wrapper:uint(optFlag) ~= 0 then 
        local inner_tree = createSubTree2(block_tree, msg_buf(840, 16), "ueArrivalTime")
        p_wrapper:subtree_add(inner_tree, isarProto.fields[lhsName .. "_hasUeArrivalTime"], optFlag)
        current = msg_buf(848 , 8)
        p_wrapper:subtree_add(inner_tree, isarProto.fields[lhsName .. "_ueArrivalTime"], current)
        
      else 
        local replacement_text = p_wrapper:subtree_add(block_tree, isarProto.fields[lhsName .. "_hasUeArrivalTime"], optFlag)

        replacement_text:set_text("ueArrivalTime: <omit>")
      end 
    end 
  return ( actual_offset + totalStructSize )
end 

