-- hook for inserting our decoders into Wireshark's Dissector framework

function isarProto.dissector (buf, pkt, root) 
  root_tree = root
  pktinfo = pkt
  
  local subtree = root:add(isarProto, buf())

  subtree = subtree:add(buf(), "")

  local msgId = f_msgId().value
  local msgName = msgIds[msgId]
  wrapper:init()
  pkt.cols.info = str_format("%s: 0x%04x", msgName, msgId)
  subtree:set_text(str_format("%s:", msgName))
  builders[msgName](wrapper, buf, subtree, "", "f_" .. msgName, 0, msgName)
end 


